css:
.p18-page { display: grid; grid-template-rows: auto 1fr; min-height: 100cqh; overflow-x: clip; }
.p18-page > .deck { grid-row: 2; align-self: center; }
.p18-top { display: grid; gap: var(--s-2); width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3) var(--s-3) 0; grid-row: 1; }
.p18-top:empty { display: none; }
.p18-strip { --p18-sh: 9rem; }
.p18-strip--b { --p18-sh: 4.5rem; }
.p18-strip .deck { --card: max(var(--card-min), min(var(--card-max), calc(100cqw - 2rem), calc(100cqh - 2rem - var(--peek) - var(--s-3) - var(--controls-h) - var(--p18-sh)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p18-strip { --p18-sh: 17rem; } .p18-strip--b { --p18-sh: 6rem; } }
@media (max-width: 21.25rem) { .p18-strip { --p18-sh: 22rem; } .p18-strip--b { --p18-sh: 7rem; } }
.p18-win .deck-card__head { margin-top: 0; }
.p18-face { gap: var(--s-2); }
.p18-body { flex: 1 1 auto; min-height: 0; overflow: auto; display: grid; grid-auto-rows: min-content; gap: var(--s-3); align-content: start; padding-block: var(--s-1) var(--s-2); border-bottom: var(--w1) solid var(--rule); }
.p18-msg { flex: none; display: grid; gap: var(--s-2); }
.p18-msg:empty { display: none; }
.p18-foot { flex: none; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: var(--s-2); }
.dialog__foot.p18-foot2 { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); }
.p18-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -1); }
.p18-area { position: relative; }
.p18-count { position: absolute; right: var(--s-2); bottom: var(--s-1); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); pointer-events: none; background: var(--white); padding-inline: var(--s-1); }
.p18-count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.textarea.p18-ta { min-height: 4rem; padding-bottom: 1.375rem; resize: none; }
.p18-pair { display: grid; grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr)); gap: var(--s-3); align-items: start; }
.p18-pair .field { grid-template-columns: minmax(0, 1fr); }
.p18-pair .select { height: auto; min-width: 0; padding-block: var(--s-2); }
.p18-pair .select > span { min-width: 0; flex: 1 1 auto; overflow: hidden; overflow-wrap: anywhere; }
.p18-pair .select .motive { display: flex; max-width: 100%; }
.p18-pair + .menu { margin-top: calc(var(--s-2) * -1); }
.p18-full { grid-column: 1 / -1; }
.textarea.p18-name { min-height: var(--ctl-h); padding: var(--s-2) var(--s-3); resize: none; overflow-wrap: anywhere; }
.btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p18-tipw { position: relative; display: flex; min-width: 0; }
.p18-tipw > .btn { flex: 1 1 auto; width: 100%; }
.p18-tip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.p18-win .hint { font-size: var(--fs-small); }
.p18-fade { opacity: 0.5; }
.p18-pressed { border-width: var(--w2); border-color: var(--ink); text-decoration: underline; text-underline-offset: 0.25em; }

.dialog.p18-dlg { max-height: 100%; }
.dialog__foot.p18-foot3 { flex-direction: column; }
.dialog__foot.p18-foot3 > * { flex: none; }
.p18-dlg .dialog__body p + p { color: var(--muted); }
.p18-dlg .banner { padding-inline: var(--s-3); }
.p18-dlg .dialog__foot .p18-tipw { position: relative; }
.p18-dtip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }

.p18-lpage { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; height: 100cqh; min-height: 18rem; width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3); gap: var(--s-3); overflow-x: clip; }
.p18-lhead { display: grid; gap: var(--s-3); }
.p18-lhead > .p18-top { grid-row: auto; padding: 0; max-width: none; }
.p18-gridwrap { min-height: 0; overflow: auto; padding: 2px; }
.p18-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--s-3); align-content: start; }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p18-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.p18-tile { position: relative; aspect-ratio: 1; min-width: 7.5rem; background: var(--white); }
.p18-tile__open { position: absolute; inset: 0; width: 100%; display: flex; align-items: flex-start; padding: var(--s-3) calc(var(--hit) + var(--s-1)) var(--s-3) var(--s-3); border: 0; border-radius: var(--r); background: transparent; color: var(--ink); text-align: start; font: inherit; cursor: pointer; }
.p18-tile__name { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; font-size: var(--fs-body); line-height: var(--lh-small); font-weight: var(--fw-bold); overflow-wrap: anywhere; }
.p18-tile__chev { position: absolute; right: var(--s-3); bottom: var(--s-3); }  
.p18-tile .ibtn { position: absolute; top: var(--s-1); right: var(--s-1); }
.p18-tile .tip { position: absolute; z-index: 5; top: calc(var(--hit) + var(--s-1)); left: var(--s-1); right: var(--s-1); max-width: none; }
.p18-fade { position: relative; }
.p18-lfoot { display: flex; justify-content: center; }
.p18-lfoot .btn { min-width: 9rem; }
.p18-center { display: grid; justify-items: center; align-content: center; gap: var(--s-2); text-align: center; padding: var(--s-5) var(--s-3); height: 100%; }
.p18-center p { max-width: var(--measure); }
.p18-err { text-align: start; display: grid; gap: var(--s-3); justify-items: start; max-width: 32rem; width: 100%; margin-inline: auto; align-content: center; }
.p18-err .banner { width: 100%; }
.p18-hist { display: grid; gap: var(--s-2); }
.p18-note { color: var(--muted); font-size: var(--fs-small); line-height: var(--lh-small); }
.p18-win .rec { min-height: 2.5rem; padding-block: var(--s-1); }
.p18-win .rec__lead, .p18-win .rec__value { display: none; }
.p18-win .rec { grid-template-columns: minmax(0, 1fr); grid-template-areas: "title"; }
.p18-win .rec__title { grid-area: title; }
.p18-ok { margin: 0; }
.p18-ring { outline: var(--focus-ring); outline-offset: var(--focus-offset); }

@media (max-width: 21.25rem) {
  .composer { gap: var(--s-1); padding-inline: var(--s-1); }
  .composer .input { padding-inline: var(--s-1); }
  .composer .input::placeholder { font-size: var(--fs-small); }
}

.deck__stack:has(> .p18-win) { width: min(var(--card-max), calc(100cqw - 2rem)); height: auto; }
.deck__stack:has(> .p18-win) ~ .deck__controls { display: none; }
.p18-win { position: relative; left: auto; bottom: auto; width: 100%; height: auto; min-height: var(--card-min); max-height: calc(100cqh - 2rem - var(--p18-win-off, 0rem)); display: flex; flex-direction: column; }
.p18-win .deck-card__face { position: relative; inset: auto; flex: 1 1 auto; min-height: 0; }
.p18-win [class*="-body"], .p18-win .deck-card__scroll { scrollbar-width: thin; scrollbar-color: var(--line) var(--white); }
.p18-strip { --p18-win-off: 9.5rem; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p18-strip { --p18-win-off: 19.5rem; } }
@media (max-width: 21.25rem) { .p18-strip { --p18-win-off: 29.5rem; } }
.p18-strip.p18-strip--b { --p18-win-off: 5.5rem; }
@media (max-width: 21.25rem) { .p18-strip.p18-strip--b { --p18-win-off: 8rem; } }

.p18-dlg .dialog__foot:has(.p18-tipw) { display: grid; grid-template-columns: 1fr 1fr; }
.p18-dlg .dialog__foot .p18-tipw { display: contents; }
.p18-dlg .dialog__foot .p18-tipw > .tip { position: static; translate: none; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; text-align: start; }

@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p18-dlg .dialog__head { flex-wrap: wrap; }
  .p18-dlg .dialog__head > .ibtn { order: -1; margin-inline-start: auto; }
  .p18-dlg .dialog__title { flex: 1 1 100%; }
}
@media (max-width: 21.25rem) { .scrim { padding: var(--s-3); } }

.p18-tile { aspect-ratio: auto; min-height: 7.5rem; display: flex; align-items: flex-end; }
.p18-tile.frame--full { --frame-color: var(--line); }
.p18-tile__name { overflow-wrap: break-word; }
.p18-gridwrap { padding: var(--w2); }
@media (max-width: 21.25rem) { .p18-grid { grid-template-columns: minmax(0, 1fr); } }

.p18-tile .tip { position: relative; top: auto; left: auto; right: auto; z-index: 5; margin: var(--s-1); }
.p18-tile .tip.only-wide { display: none; }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p18-tile .tip.only-wide { display: inline-block; } }
.p18-hov { border-color: var(--ink); }
